<div class="container"><div class="top-bar"><h2>Data Anggota Kelompok</h2><a href="{{ route('admin.dashboard') }}" class="btn btn-dashboard"><i class="fas fa-arrow-left"></i> Dashboard</a></div><div class="filter-group"><input type="text" id="search" placeholder="Cari nama / NIK..."><select id="filterKelompok"><option value="">Semua Kelompok</option>@foreach($daftarKelompok as $k)<option value="{{ $k->nama_kelompok }}">{{ $k->nama_kelompok }}</option>@endforeach</select><button class="btn btn-print" onclick="window.print()"><i class="fas fa-print"></i> Cetak</button></div><table id="tabelData"><tr><th style="width:50px;text-align:center">No</th><th>Nama Anggota</th><th>NIK</th><th style="text-align:center">Jenis Kelamin</th><th>Kelompok</th><th style="text-align:center">Luas Garapan</th><th>Komoditas</th></tr>@forelse($anggota as $i=>$a)<tr><td style="text-align:center">{{ $i+1 }}</td><td>{{ $a->nama_anggota ?? '-' }}</td><td>{{ $a->nik ?? '-' }}</td><td style="text-align:center">{{ $a->jenis_kelamin ?? '-' }}</td><td>{{ $a->nama_kelompok ?? '-' }}</td><td style="text-align:center">{{ $a->luas_garapan ?? '-' }}</td><td>{{ $a->komoditas_utama ?? '-' }}</td></tr>@empty<tr><td colspan="7">Data belum tersedia</td></tr>@endforelse</table></div></div>
<script>var search=document.getElementById('search');document.querySelectorAll('#tabelData tr').forEach(function(row,i){if(i===0)return;search.addEventListener('keyup',function(){var k=this.value.toLowerCase();var n=row.cells[1].innerText.toLowerCase();var nik=row.cells[2].innerText.toLowerCase();row.style.display=(n.includes(k)||nik.includes(k))?'':'none'})});var f=document.getElementById('filterKelompok');f.addEventListener('change',function(){var v=this.value.toLowerCase();document.querySelectorAll('#tabelData tr').forEach(function(row,i){if(i===0)return;row.style.display=(v==='')?'':(row.cells[4].innerText.toLowerCase().includes(v)?'':'none')})});var b=document.getElementById('notifBtn'),d=document.getElementById('notifDropdown');if(b){b.addEventListener('click',function(e){e.stopPropagation();d.classList.toggle('show')});window.addEventListener('click',function(){d.classList.remove('show')})}</script>
